mapper.select:
SELECT 
FROM machines mac
LEFT JOIN agents a ON mac.agent_id = a.id
LEFT JOIN merchants m ON mac.merchant_id = m.id
WHERE 1=1

    AND mac.agent_id = #{agentId}


    AND mac.merchant_id = #{merchantId}


    AND mac.machine_sn LIKE CONCAT('%', #{machineSn}, '%')


    AND mac.status = #{status}

ORDER BY mac.create_time DESC
